package pfm.android;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import android.content.Context;

public class EuropaHarness {
    static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
    static HashMap<String,String> countries(NativeCareerStore.Career c){HashMap<String,String> map=new HashMap<>();for(NativeCareerStore.Club club:c.clubs)map.put(club.id,club.league);return map;}
    static void groups(ArrayList<ArrayList<String>> groups,ArrayList<ArrayList<String>> ucl,NativeCareerStore.Career c){groups(groups,ucl,c,null);}
    static void groups(ArrayList<ArrayList<String>> groups,ArrayList<ArrayList<String>> ucl,NativeCareerStore.Career c,MatchJournal journal){
        HashMap<String,String> country=countries(c);Set<String> used=EuropaSeason.entrants(groups),cl=EuropaSeason.entrants(ucl);check(groups.size()==12&&used.size()==48,"Europa entrant count");for(String id:used)check(!cl.contains(id),"club in both group stages");for(ArrayList<String> group:groups){HashSet<String> countries=new HashSet<>();check(group.size()==4,"group size");for(String id:group)check(countries.add(country.get(id)),"group country clash");}
        for(String code:NativeWorldCenter.C){int n=0;for(String id:used)if(id.startsWith(code+":"))n++;int extra=0;if(journal!=null)for(String id:EuropeanQualification.ids(journal.metadata("uel-from-uclq")))if(id.startsWith(code+":"))extra++;check(n==3+extra,"Europa quota plus playoff transfers "+code+" "+n);}
    }
    static void qualification(String world,File root)throws Exception{
        JournalHarness.world(world,930);NativeCareerStore.Career c=NativeCareerStore.current;MatchJournal previous=new MatchJournal(root,930,2010);for(String code:NativeWorldCenter.C)for(NativeWorldCenter.M fixture:NativeWorldCenter.schedule(NativeWorldCenter.leagues.get(code).size())){MatchJournal.Match m=new MatchJournal.Match();m.competition="league:"+code;m.round=fixture.r;m.home=code+":"+fixture.h;m.away=code+":"+fixture.a;m.homeGoals=1;m.id=NativeMatchJournal.key(m.competition,m.round,m.home,m.away);previous.put(m);}
        String holder=UclSeason.standings(previous,"en",c.clubs).get(19).id;MatchJournal.Match finalMatch=new MatchJournal.Match();finalMatch.id="uel-final";finalMatch.competition="uel:2010";finalMatch.home=holder;finalMatch.away="fr:0";finalMatch.round=15;finalMatch.winner=holder;previous.put(finalMatch);
        for(String code:NativeWorldCenter.C){check(EuropeanPlaces.europa(code)==3,"quota policy");int from=EuropeanPlaces.champions(code)+1;check(EuropeanPlaces.zone(code,from,20)==0xffffefc2&&EuropeanPlaces.zone(code,from+2,20)==0xffffefc2&&EuropeanPlaces.zone(code,from+3,20)==0,"table zone does not match three Europa places");}
        for(int seed=0;seed<50;seed++){MatchJournal next=new MatchJournal(root,10000+seed,2011);ArrayList<ArrayList<String>> cl=UclSeason.prepare(next,previous,c,seed),el=EuropaSeason.prepare(next,previous,c,cl,seed^93);groups(el,cl,c);Set<String> all=EuropaSeason.entrants(el);check(all.contains(holder),"Europa holder omitted");for(String code:NativeWorldCenter.C)for(String id:EuropaSeason.leaguePlaces(code,previous,c,EuropaSeason.entrants(cl),UclSeason.strengths(c),holder))check(all.contains(id),"league place omitted");String frozen=UclSeason.encode(el);check(frozen.equals(UclSeason.encode(EuropaSeason.prepare(next,previous,c,cl,987))),"Europa redraw");}
        System.out.println("Quotas: 3 UEL places for every top-five league, matching table zones; 50 country-separated draws, no UCL overlap, table qualification and holder entry verified");
    }
    static void transfers(Context context,MatchJournal journal,NativeCareerStore.Career career)throws Exception{
        String value=journal.metadata("uel-from-ucl");check(value!=null,"UCL transfer list missing");ArrayList<String> moved=new ArrayList<>(Arrays.asList(value.split(";")));check(moved.size()==8&&new HashSet<>(moved).size()==8,"transfer count");Set<String> expected=new HashSet<>();HashMap<String,Integer> groupOf=new HashMap<>();int g=0;for(ArrayList<String> group:NativeMatchJournal.uclGroups(context,journal.season())){ArrayList<UclKnockout.Row> table=UclKnockout.table(group,journal.competition("ucl:"+journal.season()));expected.add(table.get(2).id);}check(expected.equals(new HashSet<>(moved)),"wrong UCL clubs transferred");
        ArrayList<ArrayList<String>> groups=NativeMatchJournal.europaGroups(context,journal.season());HashMap<String,String> countries=countries(career);HashSet<String> seeded=new HashSet<>(moved.subList(0,4)),unseeded=new HashSet<>(moved.subList(4,8));for(ArrayList<String> group:groups){ArrayList<UclKnockout.Row> table=UclKnockout.table(group,journal.competition("uel:"+journal.season()));seeded.add(table.get(0).id);unseeded.add(table.get(1).id);for(String id:group)groupOf.put(id,g);g++;}
        ArrayList<String[]> draw=NativeMatchJournal.europaDraw(context,journal.season(),0);check(draw.size()==16,"last-32 pair count");for(String[] tie:draw){check(unseeded.contains(tie[0])&&seeded.contains(tie[1]),"seeding / second-leg home");check(!countries.get(tie[0]).equals(countries.get(tie[1])),"last-32 country clash");if(groupOf.containsKey(tie[0])&&groupOf.containsKey(tie[1]))check(!groupOf.get(tie[0]).equals(groupOf.get(tie[1])),"same group paired");}
    }
    public static void main(String[] args)throws Exception{
        File root=new File(args[1]);root.mkdirs();qualification(args[0],new File(root,"qualification"));
        MatchEffects discipline=new MatchEffects();MatchEffects.Discipline d=discipline.discipline("ucl:2010","player");d.ban=1;check(!discipline.available("player","uel:2010")&&discipline.available("player","league:en"),"UCL suspension not shared with UEL / leaked domestic");check(discipline.readDiscipline("uel:2010","player").ban==1,"discipline projection mismatch");
        discipline.discipline("ucl:2010","cards").yellow=2;MatchJournal.Match caution=new MatchJournal.Match();caution.id="uel-caution";caution.competition="uel:2010";caution.effectsVersion=2;MatchJournal.PlayerFact card=new MatchJournal.PlayerFact();card.uid="cards";card.yellow=1;card.stats[2]=1;caution.players.add(card);discipline.apply(caution);check(discipline.readDiscipline("ucl:2010","cards").ban==1,"third European caution did not suspend across competitions");MatchJournal.Match serve=new MatchJournal.Match();serve.id="uel-serve";serve.competition="uel:2010";serve.effectsVersion=2;MatchJournal.PlayerFact absent=new MatchJournal.PlayerFact();absent.uid="cards";serve.players.add(absent);discipline.apply(serve);discipline.apply(serve);check(discipline.available("cards","uel:2010")&&discipline.available("cards","ucl:2010"),"European suspension not served once in Europa");
        MatchJournal previous=null;String nextCl=null;
        for(String active:new String[]{"en","de"}){int nonce=active.equals("en")?931:932;File dir=new File(root,active);dir.mkdirs();Context context=new Context("overrides/app/src/main/assets",dir);AndroidRuntime.current=context;JournalHarness.world(args[0],nonce);NativeCareerStore.current.activeLeague=active;int total=active.equals("de")?34:38;
            for(int year=2010;year<=2011;year++){NativeWorldCenter.year=year;NativeWorldCenter.played=0;NativeMatchJournal.advance(context,0);HashMap<String,String> prefix=new HashMap<>();for(int step=1;step<=total;step++){NativeWorldCenter.played=step;NativeMatchJournal.advance(context,step);if(step==19||step==24){MatchJournal saved=JournalHarness.open(context,nonce,year);prefix.clear();for(MatchJournal.Match m:saved.all())prefix.put(m.id,JournalHarness.frozen(m));JournalHarness.restart();NativeMatchJournal.advance(context,step);saved=JournalHarness.open(context,nonce,year);for(Map.Entry<String,String> e:prefix.entrySet())check(e.getValue().equals(JournalHarness.frozen(saved.get(e.getKey()))),"restart changed report");}}
                MatchJournal journal=JournalHarness.open(context,nonce,year);check(journal.size()==2249+journal.competition("uclq:"+year).size()&&journal.competition("ucl:"+year).size()==125,"calendar count / UCL regression");ArrayList<MatchJournal.Match> matches=journal.competition("uel:"+year);check(matches.size()==205&&EuropaSeason.champion(journal).length()>0,"Europa incomplete");int[] count=new int[16];for(MatchJournal.Match m:matches){count[m.round]++;check(m.effectsVersion>0,"fresh Europa match has no effects");int hg=0,ag=0,subsHome=0,subsAway=0;for(MatchJournal.PlayerFact p:m.players){if(p.club.equals(m.home)){hg+=p.stats[0];if(p.minutes>0&&p.stats[3]==0)subsHome++;}else{ag+=p.stats[0];if(p.minutes>0&&p.stats[3]==0)subsAway++;}check(p.minutes<=m.duration,"minutes exceed duration");}check(hg==m.homeGoals&&ag==m.awayGoals&&subsHome<=3&&subsAway<=3,"Europa goal/substitution ledger");}check(count[1]==24&&count[7]==16&&count[9]==8&&count[11]==4&&count[13]==2&&count[15]==1,"stage sizes");groups(NativeMatchJournal.europaGroups(context,year),NativeMatchJournal.uclGroups(context,year),NativeCareerStore.current,journal);transfers(context,journal,NativeCareerStore.current);
                byte[] bytes=Files.readAllBytes(new File(dir,"match-journals/matches-"+nonce+"-"+year+".bin").toPath());NativeMatchJournal.europa(context,year);NativeMatchJournal.europaDraw(context,year,4);check(Arrays.equals(bytes,Files.readAllBytes(new File(dir,"match-journals/matches-"+nonce+"-"+year+".bin").toPath())),"Europa history view wrote data");if(year==2010){previous=journal;nextCl=UclSeason.encode(UclSeason.prepare(new MatchJournal(new File(root,"legacy-next"),nonce,2011),journal,NativeCareerStore.current,123));}}
            System.out.println("Calendar "+active+": two Europa seasons, 410 fixtures, 8 correct UCL transfers per season, seeded round of 32, annual champions, restart and read-only history verified");}
        File dir=new File(root,"upgrade");dir.mkdirs();Context context=new Context("overrides/app/src/main/assets",dir);AndroidRuntime.current=context;JournalHarness.world(args[0],933);NativeCareerStore.current.activeLeague="de";MatchJournal old=JournalHarness.open(context,933,2010);HashMap<String,String> before=new HashMap<>();for(MatchJournal.Match m:previous.all())if(!m.competition.startsWith("uel:")&&!m.competition.startsWith("cup:")){old.put(m);before.put(m.id,JournalHarness.frozen(m));}old.save();MatchJournal next=JournalHarness.open(context,933,2011);next.define("ucl-groups",nextCl);next.save();NativeWorldCenter.played=34;JournalHarness.restart();NativeMatchJournal.advance(context,34);MatchJournal updated=JournalHarness.open(context,933,2010);for(Map.Entry<String,String> e:before.entrySet())check(e.getValue().equals(JournalHarness.frozen(updated.get(e.getKey()))),"upgrade changed saved fixture");for(MatchJournal.Match m:updated.competition("uel:2010"))check(m.effectsVersion==0&&m.homeCredit==0&&m.awayCredit==0&&m.source.equals("reconstructed-v93"),"retroactive Europa consequences");check(updated.competition("uel:2010").size()==205&&nextCl.equals(JournalHarness.open(context,933,2011).metadata("ucl-groups")),"upgrade rewrote frozen UCL / missing Europa");
        System.out.println("PASS: v92 upgrade preserves 1,951 existing match facts and frozen next UCL draw; 205 Europa fixtures backfilled without retrospective effects or finance");
    }
}
